cypress_script:
describe('Product Images and Accessible Form Fields', () => {
  before(() => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
  });

  it('should have alt texts for all product images', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="item-0-title-link"]').should('be.visible');
    cy.get('[data-test="item-1-title-link"]').should('be.visible');
    cy.get('[data-test="item-2-title-link"]').should('be.visible');
    cy.get('[data-test="item-3-title-link"]').should('be.visible');
    cy.get('[data-test="item-4-title-link"]').should('be.visible');
    cy.get('[data-test="item-5-title-link"]').should('be.visible');
  });

  it('should ensure buttons are accessible', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').should('be.visible');
    cy.get('[data-test="add-to-cart-sauce-labs-bike-light"]').should('be.visible');
    cy.get('[data-test="add-to-cart-sauce-labs-bolt-t-shirt"]').should('be.visible');
    cy.get('[data-test="add-to-cart-sauce-labs-fleece-jacket"]').should('be.visible');
    cy.get('[data-test="add-to-cart-sauce-labs-onesie"]').should('be.visible');
    cy.get('[data-test="add-to-cart-test.allthethings()-t-shirt-(red)"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Product Images and Accessible Form Fields', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
  });

  test('should have alt texts for all product images', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await expect(page.locator('[data-test="item-0-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-1-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-2-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-3-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-4-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-5-title-link"]')).toBeVisible();
  });

  test('should ensure buttons are accessible', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await expect(page.locator('[data-test="add-to-cart-sauce-labs-backpack"]')).toBeVisible();
    await expect(page.locator('[data-test="add-to-cart-sauce-labs-bike-light"]')).toBeVisible();
    await expect(page.locator('[data-test="add-to-cart-sauce-labs-bolt-t-shirt"]')).toBeVisible();
    await expect(page.locator('[data-test="add-to-cart-sauce-labs-fleece-jacket"]')).toBeVisible();
    await expect(page.locator('[data-test="add-to-cart-sauce-labs-onesie"]')).toBeVisible();
    await expect(page.locator('[data-test="add-to-cart-test.allthethings()-t-shirt-(red)"]')).toBeVisible();
  });
});
